49	        runTAdd<half, kGRows_, kGCols_, kTRows_, kTCols_>((half*)(out), (half*)(src0), (half*)(src1));
50	    else
51	        runTAdd<T, kGRows_, kGCols_, kTRows_, kTCols_>(out, src0, src1);
52	}
