40	#define CHECK_RESULT_GTEST(x) \
41	    if (!(x))                 \
42	        ASSERT_TRUE(false);
43	
44	typedef enum {
45	    DT_UNDEFINED = -1,
46	    FLOAT = 0,
47	    HALF = 1,
48	    INT8_T = 2,
49	    INT32_T = 3,
50	    UINT8_T = 4,
51	    INT16_T = 6,
52	    UINT16_T = 7,
53	    UINT32_T = 8,
