63	
64	bool ReadFile(const std::string& filePath, size_t& fileSize, void* buffer, size_t bufferSize)
65	{
66	    struct stat sBuf;
67	    int fileStatus = stat(filePath.data(), &sBuf);
68	    if (fileStatus == -1) {
69	        ERROR_LOG("Failed to get file. Path = %s", filePath.c_str());
70	        return false;
71	    }
72	    if (S_ISREG(sBuf.st_mode) == 0) {
73	        ERROR_LOG("%s is not a file, please enter a file", filePath.c_str());
74	        return false;
75	    }
76	
77	    std::ifstream file;
78	    file.open(filePath, std::ios::binary);
79	    if (!file.is_open()) {
80	        ERROR_LOG("Open file failed. Path = %s", filePath.c_str());
81	        return false;
82	    }
83	
84	    std::filebuf* buf = file.rdbuf();
85	    size_t size = buf->pubseekoff(0, std::ios::end, std::ios::in);
86	    if (size == 0) {
87	        ERROR_LOG("file size is 0");
88	        file.close();
89	        return false;
90	    }
91	    if (size > bufferSize) {
92	        ERROR_LOG("%s: file size (%lu) is larger than buffer size (%lu)", filePath.c_str(), size, bufferSize);
93	        file.close();
94	        return false;
95	    }
96	    buf->pubseekpos(0, std::ios::in);
97	    buf->sgetn(static_cast<char*>(buffer), size);
98	    fileSize = size;
99	    file.close();
100	    return true;
101	}
102	
103	bool WriteFile(const std::string& filePath, const void* buffer, size_t size)
104	{
105	    if (buffer == nullptr) {
106	        ERROR_LOG("Write file failed. buffer is nullptr");
107	        return false;
108	    }
109	
110	#ifdef _WIN32
111	    int fd = open(filePath.c_str(), O_RDWR | O_CREAT | O_TRUNC | O_BINARY, S_IRUSR | S_IWRITE);
112	#else
113	    int fd = open(filePath.c_str(), O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWRITE);
114	#endif
115	    if (fd < 0) {
116	        ERROR_LOG("Open file failed. path = %s", filePath.c_str());
117	        return false;
118	    }
119	
120	    auto writeSize = write(fd, buffer, size);
121	    (void)close(fd);
122	    if (writeSize != size) {
123	        ERROR_LOG("Write file Failed.");
124	        return false;
125	    }
126	
127	    return true;
128	}
129	
130	template <typename T>
131	void DoPrintData(const T* data, size_t count, size_t elementsPerRow)
132	{
133	    assert(elementsPerRow != 0);
134	    for (size_t i = 0; i < count; ++i) {
135	        std::cout << std::setw(5) << data[i];
136	        if (i % elementsPerRow == elementsPerRow - 1) {
137	            std::cout << std::endl;
138	        }
139	    }
140	}
141	
142	void DoPrintHalfData(const aclFloat16* data, size_t count, size_t elementsPerRow)
143	{
144	    assert(elementsPerRow != 0);
145	    for (size_t i = 0; i < count; ++i) {
146	        std::cout << std::setw(5) << std::setprecision(6) <<
147	#if defined(__CPU_SIM) || defined(__COSTMODEL)
148	            (float)data[i];
149	#else
150	            aclFloat16ToFloat(data[i]);
151	#endif
152	        if (i % elementsPerRow == elementsPerRow - 1) {
153	            std::cout << std::endl;
154	        }
155	    }
156	}
157	
158	void PrintData(const void* data, size_t count, printDataType dataType, size_t elementsPerRow = 16)
159	{
160	    if (data == nullptr) {
161	        ERROR_LOG("Print data failed. data is nullptr");
162	        return;
163	    }
164	
165	    switch (dataType) {
166	        case BOOL:
167	            DoPrintData(reinterpret_cast<const bool*>(data), count, elementsPerRow);
168	            break;
169	        case INT8_T:
170	            DoPrintData(reinterpret_cast<const int8_t*>(data), count, elementsPerRow);
171	            break;
172	        case UINT8_T:
173	            DoPrintData(reinterpret_cast<const uint8_t*>(data), count, elementsPerRow);
174	            break;
175	        case INT16_T:
176	            DoPrintData(reinterpret_cast<const int16_t*>(data), count, elementsPerRow);
177	            break;
178	        case UINT16_T:
179	            DoPrintData(reinterpret_cast<const uint16_t*>(data), count, elementsPerRow);
180	            break;
181	        case INT32_T:
182	            DoPrintData(reinterpret_cast<const int32_t*>(data), count, elementsPerRow);
183	            break;
184	        case UINT32_T:
185	            DoPrintData(reinterpret_cast<const uint32_t*>(data), count, elementsPerRow);
186	            break;
187	        case INT64_T:
188	            DoPrintData(reinterpret_cast<const int64_t*>(data), count, elementsPerRow);
189	            break;
190	        case UINT64_T:
191	            DoPrintData(reinterpret_cast<const uint64_t*>(data), count, elementsPerRow);
192	            break;
193	
194	        case HALF:
195	            DoPrintHalfData(reinterpret_cast<const aclFloat16*>(data), count, elementsPerRow);
196	            break;
197	
198	        case FLOAT:
199	            DoPrintData(reinterpret_cast<const float*>(data), count, elementsPerRow);
200	            break;
201	        case DOUBLE:
202	            DoPrintData(reinterpret_cast<const double*>(data), count, elementsPerRow);
