232	inline uint32_t ReadEnvU32(const char* name, uint32_t fallback)
233	{
234	    const char* value = std::getenv(name);
235	    if (value == nullptr || *value == '\0') {
236	        return fallback;
237	    }
238	    char* end = nullptr;
239	    const unsigned long parsed = std::strtoul(value, &end, 10);
240	    if (end == value || *end != '\0') {
241	        return fallback;
242	    }
243	    return parsed == 0 ? fallback : static_cast<uint32_t>(parsed);
244	}
245	
246	inline bool ReadEnvBool(const char* name, bool fallback)
247	{
248	    const char* value = std::getenv(name);
249	    if (value == nullptr || *value == '\0') {
250	        return fallback;
251	    }
252	    if (std::strcmp(value, "0") == 0 || std::strcmp(value, "false") == 0 || std::strcmp(value, "FALSE") == 0) {
253	        return false;
254	    }
255	    if (std::strcmp(value, "1") == 0 || std::strcmp(value, "true") == 0 || std::strcmp(value, "TRUE") == 0) {
256	        return true;
257	    }
258	    return fallback;
259	}
