inline uint32_t get_block_idx()
{
    if (auto hook = pto::cpu_sim::ResolveExecutionContextHook(); hook != nullptr) {
        uint32_t block_idx = 0;
        uint32_t subblock_id = 0;
        uint32_t subblock_dim = 1;
        hook(&block_idx, &subblock_id, &subblock_dim);
