{
    if (pto::cpu_sim::injected_subblock_id_hook != nullptr) {
        return pto::cpu_sim::injected_subblock_id_hook();
    }
    if (auto hook = pto::cpu_sim::ResolveSubblockIdHook(); hook != nullptr) {
