def run_gen_data(golden_path):
    original_dir = os.getcwd()
    try:
        cmd = ["cp", golden_path, "build/gen_data.py"]
        run_command(cmd)

        build_dir = "build/"
        os.chdir(build_dir)

        gloden_gen_cmd = [sys.executable, "gen_data.py"]
        output = run_command(gloden_gen_cmd)
        print(output)
    except Exception as e:
        print(f"gen golden failed: {e}")
        raise
    finally:
        os.chdir(original_dir)


def needs_test_isolation(testcase):
    """CCU tests need process isolation (one mpirun per GTest case)."""
    return testcase.endswith("_ccu")


def list_gtest_cases(testcase_dir, gtest_filter="*"):
    """Parse TEST_F macros from source — no binary execution, no device access."""
    main_path = os.path.join("testcase", testcase_dir, "main.cc")
    try:
        with open(main_path) as f:
            content = f.read()
    except FileNotFoundError:
        return []
    pairs = re.findall(r"^\s*TEST_F\s*\(\s*(\w+)\s*,\s*(\w+)\s*\)", content, re.MULTILINE)
    tests = [f"{suite}.{name}" for suite, name in pairs]
    if "-" in gtest_filter:
        pos, neg = gtest_filter.split("-", 1)
        neg_patterns = [p for p in neg.split(":") if p]
        tests = [t for t in tests
                 if not any(fnmatch.fnmatch(t, p) for p in neg_patterns)]
    elif gtest_filter != "*":
        patterns = [p for p in gtest_filter.split(":") if p]
        tests = [t for t in tests
                 if any(fnmatch.fnmatch(t, p) for p in patterns)]
    return tests


RANK_LEVELS = [2, 4, 8]


def detect_npu_count():
    """Count available NPU devices on this host.

    Probes /dev/davinci0, /dev/davinci1, ... (excluding davinci_manager/devmm_svm).
    Returns the count, or None if /dev/davinci* devices are not present (likely
    running on a host without NPUs — let downstream checks decide).
    """
    import glob
    pattern = re.compile(r"^/dev/davinci(\d+)$")
    devs = [p for p in glob.glob("/dev/davinci*") if pattern.match(p)]
    if not devs:
        return None
    return len(devs)


def get_gtest_filter_for_nranks(nranks):
    """Build GTEST_FILTER based on test naming convention (*_NRanks / *_Nranks)."""
    if nranks == 2:
        return "*-*4Ranks*:*4ranks*:*8Ranks*:*8ranks*"
    elif nranks == 4:
        return "*4Ranks*:*4ranks*"
    elif nranks == 8:
        return "*8Ranks*:*8ranks*"
    return "*"


def find_mpirun():
    """Find mpirun executable, checking MPI_HOME and common paths."""
    mpi_home = os.environ.get("MPI_HOME", "")
    if mpi_home:
        candidate = os.path.join(mpi_home, "bin", "mpirun")
        if os.path.isfile(candidate):
            return candidate

    candidates = ["/usr/local/mpich/bin/mpirun", "/usr/local/bin/mpirun", "/usr/bin/mpirun"]
    for c in candidates:

        cxx = cmake_friendly_path(cxx)
    if cc:
        cc = cmake_friendly_path(cc)

    logging.info("Final Compiler Selection -> CXX: %s, CC: %s", cxx, cc)
    return cxx, cc


def cmake_build(build_dir: Path, build_type: str) -> None:
    cmd: List[str] = ["cmake", "--build", str(build_dir), "--parallel"]

    # Multi-config generators (e.g. VS) need --config; single-config ignores it.
    cmd.extend(["--config", build_type])
    run_command(cmd)


def generate_golden(build_dir: Path, gen_script: Path) -> None:
    dst = build_dir / "gen_data.py"
    st_dir = gen_script.resolve().parent.parent.parent
    shutil.copyfile(gen_script, dst)

    env = os.environ.copy()
    pp = env.get("PYTHONPATH", "")
    new_path = str(st_dir)
    env["PYTHONPATH"] = f"{new_path}{os.pathsep}{pp}" if pp else new_path

    run_command([sys.executable, str(dst.name)], cwd=build_dir, env=env)


def read_cmake_cache_var(build_dir: Path, var_name: str) -> Optional[str]:
    cache = build_dir / "CMakeCache.txt"
    if not cache.exists():
        return None
    try:
        for line in cache.read_text(encoding="utf-8", errors="replace").splitlines():
            if not line or line.startswith(("//", "#")):
                continue
            # CMakeCache format: VAR:TYPE=VALUE
            if line.startswith(f"{var_name}:"):
                _, _, value = line.partition("=")
                return value
    except OSError:
        return None
    return None


def find_binaries(build_dir: Path, build_type: str) -> Dict[str, Path]:
    bin_dir = build_dir / "bin"
    if os.name == "nt":
        config_dir = bin_dir / build_type
        if config_dir.exists():
            bin_dir = config_dir

    if not bin_dir.exists():
        return {}

    binaries: Dict[str, Path] = {}
    for p in bin_dir.iterdir():
        if not p.is_file():
            continue
        if os.name == "nt":
            if p.suffix.lower() != ".exe":
                continue
            binaries[p.stem] = p
        else:
            binaries[p.name] = p
    return binaries


def run_gtest_binary(binary: Path, gtest_filter: Optional[str], xml_output: Optional[Path], build_type: str,
                     verbose: bool) -> None:
    cmd: List[str] = [str(binary)]
    if gtest_filter:
        cmd.append(f"--gtest_filter={gtest_filter}")
    if xml_output:
        xml_output.parent.mkdir(parents=True, exist_ok=True)
        cmd.append(f"--gtest_output=xml:{xml_output}")

    # CPU ST test data is under build_dir/..., and tests use paths like "../<suite.case>/input1.bin".
    # For multi-config generators on Windows, binaries are under build/bin/<Config>/, so we run from build/bin/.
    run_cwd = binary.parent
    if os.name == "nt" and binary.parent.name.lower() == build_type.lower():
        run_cwd = binary.parent.parent
    run_command(cmd, cwd=run_cwd, verbose=verbose)


def run_binary(binary: Path, build_type: str, cwd: Optional[Path] = None) -> None:
    run_cwd = cwd or binary.parent
    if os.name == "nt" and binary.parent.name.lower() == build_type.lower():
        run_cwd = binary.parent.parent
    run_command([str(binary)], cwd=run_cwd)


